import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
const g = load(process.argv[2]);
const [W, H, D] = g.size;
const hi = {};
for (const c of g.cells.values()) {
  if (c.pos[1] >= 7) { const k = `${c.block.replace("minecraft:", "")}@y${c.pos[1]}`; hi[k] = (hi[k] || 0) + 1; }
}
console.log("y>=7 census:", Object.entries(hi).sort((a, b) => b[1] - a[1]).slice(0, 40));
// door halves
const bad = [];
for (const c of g.cells.values()) {
  if (!c.block.endsWith("_door")) continue;
  const [x, y, z] = c.pos; const half = c.state?.half;
  const other = g.get(x, half === "upper" ? y - 1 : y + 1, z);
  if (!other || !other.block.endsWith("_door") || other.state?.half === half) bad.push(`${c.block} ${half} @${x},${y},${z}`);
}
console.log("door half problems:", bad.length, bad.slice(0, 20));
// hanging lamps: chain should be at y5 directly under ceiling, lantern at y4 with chain above
const lamps = [...g.cells.values()].filter((c) => c.block.endsWith("copper_lantern"));
const lampIssues = lamps.filter((c) => {
  const [x, y, z] = c.pos;
  if (c.state?.hanging === "true") return !(g.blockAt(x, y + 1, z).includes("chain"));
  return !(g.blockAt(x, y - 1, z).includes("slab") || g.blockAt(x, y - 1, z).includes("bars"));
});
console.log("lanterns:", lamps.length, "issues:", lampIssues.map((c) => `${c.pos} hanging=${c.state?.hanging}`));
// bars / fence / wall connections: count fence-like neighbours touching lanterns
console.log("size", g.size);
EOF
