// print the cells around given points: node around.mjs build.nbt x,y,z [radius]
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
const g = load(process.argv[2]);
const [x0, y0, z0] = process.argv[3].split(",").map(Number);
