for (let y = y0 + r; y >= y0 - r; y--) {
  const rows = [];
  for (let z = z0 - r; z <= z0 + r; z++) {
    const row = [];
    for (let x = x0 - r; x <= x0 + r; x++) {
      const c = g.get(x, y, z);
