      row.push((c.block.replace("minecraft:", "") + st).slice(0, 34).padEnd(12));
    }
    rows.push(`z${String(z).padStart(2)}: ` + row.join(" | "));
  }
  console.log(`y=${y}`); console.log(rows.join("\n"));
}
EOF
