import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
import { readFileSync } from "node:fs";
const g = load(process.argv[2]);
const rooms = JSON.parse(readFileSync(process.argv[3], "utf8")).rooms;
const inRoom = (x, y, z) => rooms.some(({ box: [a, b, c, d, e, f] }) => x >= a && x <= d && y >= b && y <= e && z >= c && z <= f);
const out = [];
for (let y = 1; y <= 6; y++) for (let z = 2; z <= 45; z++) for (let x = 0; x <= 35; x++) {
  const air = g.isAir(x, y, z);
  if (air && !inRoom(x, y, z)) out.push(`${x},${y},${z}`);
}
// group by y and by z-row/x-col for readability
const byY = {};
for (const s of out) { const [x, y, z] = s.split(",").map(Number); (byY[y] ??= []).push([x, z]); }
for (const [y, ps] of Object.entries(byY)) console.log(`y${y}: ${ps.length} cells`, ps.slice(0, 200).map((p) => p.join(",")).join(" "));
EOF
