// two-cell blocks must have their partner: beds (part head/foot), double plants (half lower/upper), doors (checked elsewhere)
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
const g = load(process.argv[2]);
const issues = [];
const cells = [...g.cells.values()];
for (const c of cells) {
  const [x, y, z] = c.pos;
  if (c.block.endsWith("_bed")) {
    const part = c.state?.part, f = c.state?.facing;
    const dx = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] }[f];
    const other = part === "head" ? g.get(x - dx[0], y, z - dx[1]) : g.get(x + dx[0], y, z + dx[1]);
    const ok = other && other.block === c.block && other.state?.part !== part && other.state?.facing === f;
    if (!ok) issues.push(`bed ${part} facing=${f} @${x},${y},${z}`);
  }
  if (/(rose_bush|lilac|peony|tall_grass|large_fern|sunflower)$/.test(c.block) && c.state?.half === "lower") {
    const up = g.get(x, y + 1, z);
    if (!up || up.block !== c.block || up.state?.half !== "upper") issues.push(`plant ${c.block} lower without upper @${x},${y},${z}`);
  }
  if (/(rose_bush|lilac|peony|tall_grass|large_fern|sunflower)$/.test(c.block) && c.state?.half === "upper") {
    const dn = g.get(x, y - 1, z);
    if (!dn || dn.block !== c.block || dn.state?.half !== "lower") issues.push(`plant ${c.block} upper without lower @${x},${y},${z}`);
  }
}
console.log("beds:", cells.filter((c) => c.block.endsWith("_bed")).length, "plants:", cells.filter((c) => /rose_bush|lilac/.test(c.block)).map((c) => c.pos.join(",") + ":" + (c.state?.half ?? "?")).join(" "));
console.log("pair issues:", issues.length ? issues : "none");
EOF
